#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    map<int, queue<long long>> pending;
    map<int, long long> total;
    long long time = 0;
    int gap = 1;
    bool hasEvent = false;

    for (int i = 0; i < N; ++i) {
        char type;
        int x;
        cin >> type >> x;

        if (type == 'T') {
            gap = x;
        } else {
            if (hasEvent) time += gap;
            hasEvent = true;
            gap = 1;

            total.try_emplace(x, 0);
            if (type == 'R') {
                pending[x].push(time);
            } else if (!pending[x].empty()) {
                total[x] += time - pending[x].front();
                pending[x].pop();
            }
        }
    }

    for (auto &[friendId, responseTime] : total) {
        if (!pending[friendId].empty()) responseTime = -1;
        cout << friendId << ' ' << responseTime << '\n';
    }

    return 0;
}
